:root{--bg:#f4f6fb;--card:#fff;--ink:#1f2733;--muted:#6b7686;--primary:#1a56db;--primary-soft:#e8efff;--accent:#0f9d76;--warn:#b8860b;--line:#e3e8f0;--shadow:0 2px 12px rgba(26,42,84,.06);--radius:14px}
*{box-sizing:border-box}
body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei","Helvetica Neue",Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.6}
.wrap{max-width:1180px;margin:0 auto;padding:0 20px}
.topbar{background:linear-gradient(120deg,#142e6e,#1a56db);color:#fff;padding:16px 0;box-shadow:var(--shadow)}
.brand{display:flex;align-items:center;gap:16px}
.logo{width:48px;height:48px;border-radius:12px;background:#fff;color:var(--primary);display:flex;align-items:center;justify-content:center;font-size:26px;font-weight:800}
.topbar h1{margin:0;font-size:22px;letter-spacing:2px}
.tagline{margin:2px 0 0;font-size:12px;opacity:.9}
.layout{display:flex;gap:18px;align-items:flex-start;margin:18px 0}
.sidenav{position:sticky;top:18px;flex:none;width:210px;background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:14px;box-shadow:var(--shadow)}
.sidenav .nav-title{font-size:12px;color:var(--muted);margin:0 0 10px;padding-left:6px}
.nav-item{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:10px;cursor:pointer;color:var(--ink);font-size:14px;font-weight:600;margin-bottom:6px;transition:.15s}
.nav-item:hover{background:var(--primary-soft)}
.nav-item.active{background:var(--primary);color:#fff}
.nav-item .dot{width:8px;height:8px;border-radius:50%;background:var(--accent)}
.nav-item.active .dot{background:#fff}
.nav-badge{margin-left:auto;background:var(--accent);color:#fff;font-size:11px;border-radius:999px;padding:1px 7px}
.nav-meta{margin-top:14px;padding-top:12px;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}
.content{flex:1;min-width:0}
.panel{display:block}.panel.hidden{display:none}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:22px;margin-bottom:18px;box-shadow:var(--shadow)}
.intro{background:var(--primary-soft);border-color:#cfe0ff}.intro p{margin:0}
h2{font-size:17px;margin:0 0 14px;color:var(--primary)}h3{font-size:15px;margin:0 0 10px}
label{display:block;font-size:13px;color:var(--muted);margin-bottom:0}.req{color:#d23f3f}
input,select,textarea{width:100%;margin-top:6px;padding:9px 11px;border:1px solid var(--line);border-radius:9px;font-size:14px;color:var(--ink);background:#fff;font-family:inherit}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--primary);box-shadow:0 0 0 3px var(--primary-soft)}
button{cursor:pointer;font-family:inherit}
button.primary{background:var(--primary);color:#fff;border:none;border-radius:9px;padding:10px 16px;font-size:14px;font-weight:600}
button.primary:hover{background:#1446b8}
button.ghost{background:#fff;color:var(--primary);border:1px solid var(--primary);border-radius:9px;padding:9px 14px;font-size:13px;font-weight:600}
button.ghost:hover{background:var(--primary-soft)}
button.tool{background:#fff;border:1px solid var(--line);border-radius:8px;padding:7px 12px;font-size:12.5px;color:var(--ink)}
button.tool:hover{background:var(--primary-soft);border-color:var(--primary)}
button:disabled{opacity:.55;cursor:default}
.row{display:flex;gap:12px}.row label{flex:1}
.form-table{width:100%;border-collapse:separate;border-spacing:0 4px}
.form-table th{text-align:left;width:160px;vertical-align:top;padding:10px 12px 0 0;font-size:13px;color:var(--muted);font-weight:600;white-space:nowrap}
.form-table td{padding:0}
.form-tools{display:flex;gap:8px;flex-wrap:wrap;margin:6px 0 16px}
.import-label{display:inline-flex;align-items:center;gap:6px}
.table-tools{display:flex;gap:10px;align-items:center;margin-bottom:12px}
.result-table{width:100%;border-collapse:collapse;font-size:13px;background:#fff;border:1px solid var(--line);border-radius:10px;overflow:hidden}
.result-table th,.result-table td{padding:10px 12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}
.result-table th{background:#f7f9fc;color:var(--muted);font-weight:700;font-size:12px;white-space:nowrap}
.result-table tr:last-child td{border-bottom:none}.result-table tr:hover td{background:#fafbff}
.score-pill{display:inline-flex;align-items:center;justify-content:center;min-width:42px;height:28px;border-radius:8px;color:#fff;font-weight:800;font-size:14px}
.badge{display:inline-block;font-size:11px;padding:2px 8px;border-radius:999px;margin-right:4px}
.badge.ok{background:#e6f7f0;color:var(--accent)}.badge.src{background:var(--primary-soft);color:var(--primary)}
.contact-link{color:var(--primary);font-weight:600;word-break:break-all;font-size:12px}
.row-actions{display:flex;flex-direction:column;gap:6px}
.muted{color:var(--muted);font-size:13px}
.status{color:var(--muted);font-size:14px;padding:8px 0}.status.ok{color:var(--accent)}.status.err{color:#d23f3f}
.mail-log{width:100%;border-collapse:collapse;font-size:13px;background:#fff;border:1px solid var(--line);border-radius:10px;overflow:hidden}
.mail-log th,.mail-log td{padding:9px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
.mail-log th{background:#f7f9fc;color:var(--muted);font-size:12px}
.state-sent{color:var(--accent);font-weight:700}.state-draft{color:var(--warn);font-weight:700}
.empty{color:var(--muted);font-size:13px;padding:18px;text-align:center}
.modal{position:fixed;inset:0;background:rgba(20,30,60,.45);display:flex;align-items:center;justify-content:center;z-index:50;padding:20px}
.modal.hidden{display:none}
.modal-box{background:#fff;border-radius:14px;padding:22px;width:min(720px,96vw);max-height:90vh;overflow:auto;box-shadow:0 12px 40px rgba(0,0,0,.2)}
.modal-box label{margin-bottom:12px}
.modal-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:6px}
.tip{font-size:12px;color:var(--warn);background:#fff8e8;border:1px solid #f1e2b8;border-radius:8px;padding:8px 10px;margin-bottom:12px}
.platforms{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}
.pf{border:1px solid var(--line);border-radius:10px;padding:12px}.pf a{font-weight:700;color:var(--primary);text-decoration:none}.pf .ptype{font-size:11px;color:var(--accent)}.pf p{font-size:12px;color:var(--muted);margin:6px 0 0}
.disclaimer ul{margin:0;padding-left:20px;font-size:13px;color:#3c4654}.disclaimer li{margin-bottom:8px}
code{background:#eef1f6;padding:1px 6px;border-radius:5px;font-size:12px}
.foot{color:var(--muted);font-size:12px;text-align:center;padding:22px 0}
@media(max-width:820px){.layout{flex-direction:column}.sidenav{position:static;width:100%}.form-table th{width:auto}}

