const labelSt=a=>(a||[]).map(s=>STAGE_LABELS[s]||s).join("、")||"—";
function fmt(n){return n>=10000?(n/10000).toFixed(n%10000===0?0:1)+"亿元":n+"万元";}
function scoreSector(i,p){if(!p.industry)return{s:.5,t:"未提供行业，按中性计。"};if(i.sectors.includes(p.industry))return{s:1,t:`投资领域覆盖「${SECTOR_LABELS[p.industry]}」，高度契合。`};if(i.sectors.includes("general"))return{s:.5,t:`该机构为综合型投资，未明确限定「${SECTOR_LABELS[p.industry]}」，存在对接可能但需进一步确认。`};return{s:.2,t:`公开资料未见其重点布局「${SECTOR_LABELS[p.industry]}」，契合度低。`};}
function scoreStage(i,p){if(!p.stage)return{s:.5,t:"未提供融资轮次，按中性计。"};if(i.stages.includes(p.stage))return{s:1,t:`覆盖「${STAGE_LABELS[p.stage]}」投资，阶段完全匹配。`};const idx=STAGE_ORDER.indexOf(p.stage);const adj=i.stages.some(st=>{const k=STAGE_ORDER.indexOf(st);return k>=0&&Math.abs(k-idx)===1&&st!=="debt"&&p.stage!=="debt";});if(adj)return{s:.75,t:`未直接覆盖「${STAGE_LABELS[p.stage]}」，但覆盖相邻轮次，可尝试对接。`};return{s:.2,t:`投资阶段不含「${STAGE_LABELS[p.stage]}」，阶段不匹配。`};}
function scoreCheck(i,p){const a=Number(p.amount);if(!a||a<=0)return{s:.5,t:"未提供融资金额，按中性计。"};if(a>=i.checkMin&&a<=i.checkMax)return{s:1,t:`单笔区间 ${fmt(i.checkMin)}–${fmt(i.checkMax)}，包含本次 ${fmt(a)}需求。`};const r2=a<=i.checkMax*2&&a>=i.checkMin/2;if(r2)return{s:.6,t:`单笔区间 ${fmt(i.checkMin)}–${fmt(i.checkMax)}，与本次 ${fmt(a)}接近但略有偏差。`};return{s:.25,t:`单笔区间 ${fmt(i.checkMin)}–${fmt(i.checkMax)}，与本次 ${fmt(a)}差距较大。`};}
function scoreRegion(i,p){if(!p.region)return{s:.7,t:"未提供地区，按较中性计。"};if(i.regions.includes("全国")||i.regions.includes(p.region))return{s:1,t:`覆盖地区含「${p.region}」，地域匹配。`};const ov={长三角:["上海","苏州"],珠三角:["深圳"],北京:["全国"]};const ok=(ov[p.region]||[]).some(r=>i.regions.includes(r))||(ov[i.regions[0]]||[]).includes(p.region);if(ok)return{s:.7,t:`主投区域与「${p.region}」存在协同，可关注。`};return{s:.5,t:`公开资料未见其重点布局「${p.region}」。`};}
function scoreInstrument(i,p){const w=p.instrument||"均可";if(w==="均可"||i.instrument.includes(w)||i.instrument.includes("均可"))return{s:1,t:`可对接方式含「${w==="均可"?"股权/债权":w}」，匹配。`};return{s:.4,t:`该机构以「${i.instrument.join("/")}」为主，与意向「${w}」不完全一致。`};}
function matchInvestors(p){p=p||{};return INVESTORS.filter(i=>i.verified!==false).map(inv=>{const sec=scoreSector(inv,p),stg=scoreStage(inv,p),chk=scoreCheck(inv,p),reg=scoreRegion(inv,p),ins=scoreInstrument(inv,p);const raw=sec.s*WEIGHTS.sector+stg.s*WEIGHTS.stage+chk.s*WEIGHTS.check+reg.s*WEIGHTS.region+ins.s*WEIGHTS.instrument;const score=Math.round(raw*100);const basis=[{dim:"行业契合",score:Math.round(sec.s*100),t:sec.t},{dim:"阶段匹配",score:Math.round(stg.s*100),t:stg.t},{dim:"金额区间",score:Math.round(chk.s*100),t:chk.t},{dim:"地域协同",score:Math.round(reg.s*100),t:reg.t},{dim:"融资方式",score:Math.round(ins.s*100),t:ins.t}];const contact=inv.website?{type:"官网",value:inv.website,verified:true,note:"通过机构官网「联系我们」入口获取对接方式，官网为公开可核验渠道。"}:null;return{name:inv.name,profile:inv.profile,sectorLabels:labelS(inv.sectors),stageLabels:labelSt(inv.stages),instrument:inv.instrument,source:inv.source,verified:true,score,basis,contact};}).filter(r=>r.score>=40).sort((a,b)=>b.score-a.score);}

function download(filename,text,mime){const blob=new Blob([text],{type:mime||"text/plain;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);}
function csvCell(v){return '"'+String(v==null?"":v).replace(/"/g,'""')+'"';}
function scoreColor(s){return s>=75?"#0f9d76":s>=55?"#1a56db":"#b8860b";}
const FORM_FIELDS=["companyName","industry","stage","amount","amountUnit","region","instrument","cost","highlights"];
const form=document.getElementById("planForm");
function gatherForm(){const fd=new FormData(form);const o={};FORM_FIELDS.forEach(k=>o[k]=fd.get(k)||"");return o;}
function fillForm(o){FORM_FIELDS.forEach(k=>{const el=form.elements[k];if(el&&o[k]!=null)el.value=o[k];});}
function switchPanel(p){document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.panel===p));["plan","results","mail"].forEach(k=>document.getElementById("panel-"+k).classList.toggle("hidden",k!==p));}
document.querySelectorAll(".nav-item").forEach(n=>n.addEventListener("click",()=>switchPanel(n.dataset.panel)));
document.getElementById("btnExportJson").addEventListener("click",()=>download("融资计划书.json",JSON.stringify(gatherForm(),null,2),"application/json"));
document.getElementById("btnExportCsv").addEventListener("click",()=>{const o=gatherForm();const lines=['"字段","值"'];FORM_FIELDS.forEach(k=>lines.push(csvCell(k)+","+csvCell(o[k])));download("融资计划书.csv",lines.join("\n"),"text/csv");});
document.getElementById("fileImport").addEventListener("change",async(e)=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text();if(file.name.toLowerCase().endsWith(".json")){fillForm(JSON.parse(text));}else{const lines=text.split(/\r?\n/).filter(l=>l.trim());const o={};lines.forEach((ln,i)=>{if(i===0&&ln.includes("字段"))return;const parts=ln.split(",");if(parts.length>=2){const k=parts[0].replace(/^"|"$/g,"").replace(/""/g,'"');const v=parts.slice(1).join(",").replace(/^"|"$/g,"").replace(/""/g,'"');o[k]=v;}});fillForm(o);}alert("已导入并填充表单。");}catch(err){alert("导入失败："+err.message);}e.target.value="";});
document.getElementById("btnClear").addEventListener("click",()=>form.reset());
let lastResults=null,mailLogs=[],currentMail={inv:null,subject:"",body:""};
form.addEventListener("submit",e=>{e.preventDefault();const fd=gatherForm();if(!fd.companyName||!fd.industry||!fd.stage){alert("请填写公司名称、所处行业、融资轮次。");return;}let amount=Number(fd.amount)||0;if(fd.amountUnit==="yi")amount=amount*10000;const plan=Object.assign({},fd,{amount});renderResults({results:matchInvestors(plan),web:undefined});switchPanel("results");});
function renderResults(data){lastResults=data.results;const t=document.getElementById("resultTable"),b=document.getElementById("resultBody");document.getElementById("status").style.display="none";t.style.display="";document.getElementById("resultSummary").textContent=`共 ${data.results.length} 家适配机构（已核验、可联系）`;document.getElementById("navResultCount").textContent=data.results.length;b.innerHTML=data.results.map((r,i)=>{const sc=scoreColor(r.score);const contact=r.contact?`<a class="contact-link" href="${r.contact.value}" target="_blank" rel="noopener">${r.contact.value}</a>`:'<span class="muted">—</span>';return `<tr><td><span class="score-pill" style="background:${sc}">${r.score}</span></td><td><strong>${r.name}</strong><br><span class="badge ok">已核验</span><span class="badge src">${r.source}</span></td><td>${r.sectorLabels}</td><td>${r.stageLabels}</td><td>${r.instrument.join("/")}</td><td>${r.source}</td><td><span class="badge ok">已核验</span></td><td>${contact}</td><td><button class="primary" data-send="${i}">一键发送接洽内容</button></td></tr>`;}).join("");b.querySelectorAll("button[data-send]").forEach(btn=>btn.addEventListener("click",()=>openMail(data.results[+btn.dataset.send])));}
document.getElementById("btnDownloadResults").addEventListener("click",()=>{if(!lastResults||!lastResults.length){alert("请先完成匹配。");return;}const header=["评分","机构名称","领域","轮次","方式","来源","官方联系"];const rows=lastResults.map(r=>[r.score,r.name,r.sectorLabels,r.stageLabels,r.instrument.join("/"),r.source,r.contact?r.contact.value:""]);const csv=[header.map(csvCell).join(","),...rows.map(r=>r.map(csvCell).join(","))].join("\n");download("融资匹配结果.csv",csv,"text/csv");});
function buildEmail(plan,inv){const company=plan.companyName||"贵公司";const subject=`【融资接洽】${company} 融资推介 · 适配 ${inv.score} · ${inv.name}`;const basis=(inv.basis||[]).map(b=>`· ${b.dim}：${b.text}`).join("\n");const amountTxt=plan.amount?(Number(plan.amount)>=10000?(Number(plan.amount)/10000)+"亿元":plan.amount+"万元"):"—";const body=`${inv.name} 投资团队 负责人 钧鉴：\n\n您好！我是 ${company} 的融资负责人。我司当前正推进新一轮融资，经「融资速配」平台初步适配，贵机构与本项目的适配评分为 ${inv.score} 分，特向贵团队做简要推介，期待建立接洽。\n\n【项目概况】\n${plan.highlights||"（请在计划书中补充核心技术、客户与团队亮点）"}\n\n【融资需求】\n· 所处行业：${SECTOR_LABELS[plan.industry]||plan.industry||"—"}\n· 融资轮次：${STAGE_LABELS[plan.stage]||plan.stage||"—"}\n· 融资金额：${amountTxt}\n· 所在地区：${plan.region||"不限"}\n· 意向方式：${plan.instrument||"均可"}\n· 资金成本/诉求：${plan.cost||"—"}\n\n【适配依据（平台评估）】\n${basis}\n\n【对接方式】\n本平台已核验贵机构官方渠道：${inv.contact?inv.contact.value:"请通过公开渠道获取"}。如蒙兴趣，欢迎通过上述官方入口或回覆本邮件进一步沟通。\n\n顺颂 商祺\n${company}\n（本邮件由「融资速配」平台生成，请核对收件人后发送）`;return{subject,body};}
function openMail(inv){const plan=gatherForm();const em=buildEmail(plan,inv);currentMail={inv,subject:em.subject,body:em.body};document.getElementById("mailSubject").value=em.subject;document.getElementById("mailBody").value=em.body;document.getElementById("mailTo").value="";document.getElementById("mailStatus").textContent="";document.getElementById("mailStatus").className="status";document.getElementById("mailModal").classList.remove("hidden");}
function openMailRaw(rec){currentMail={inv:null,subject:rec.subject,body:rec.body};document.getElementById("mailSubject").value=rec.subject;document.getElementById("mailBody").value=rec.body;document.getElementById("mailTo").value=rec.to||"";document.getElementById("mailStatus").textContent="";document.getElementById("mailStatus").className="status";document.getElementById("mailModal").classList.remove("hidden");}
function closeMail(){document.getElementById("mailModal").classList.add("hidden");}
document.getElementById("mailCancel").addEventListener("click",closeMail);
document.getElementById("mailDownload").addEventListener("click",()=>{const to=document.getElementById("mailTo").value.trim()||"(收件人)";const subject=document.getElementById("mailSubject").value;const body=document.getElementById("mailBody").value;const eml=`To: ${to}\nSubject: ${subject}\nMIME-Version: 1.0\nContent-Type: text/plain; charset=UTF-8\n\n${body}`;download("接洽邮件.eml",eml,"message/rfc822");});
document.getElementById("mailSend").addEventListener("click",()=>{const to=document.getElementById("mailTo").value.trim();const subject=document.getElementById("mailSubject").value;const body=document.getElementById("mailBody").value;const st=document.getElementById("mailStatus");if(!to){st.textContent="请填写经核验的收件人邮箱。";st.className="status err";return;}const mailto=`mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;window.location.href=mailto;st.textContent="ℹ️ 已调用邮件客户端发送（离线版无SMTP，亦可下载 .eml）。";st.className="status ok";addMailLog({to,inv:currentMail.inv,subject,body,status:"draft"});setTimeout(closeMail,1100);});
function addMailLog(rec){mailLogs.unshift({time:new Date().toLocaleString("zh-CN"),to:rec.to,inv:rec.inv?rec.inv.name:"",subject:rec.subject,body:rec.body,status:rec.status});renderMailLog();}
function renderMailLog(){const body=document.getElementById("mailLogBody");document.getElementById("navMailCount").textContent=mailLogs.length;if(!mailLogs.length){body.innerHTML='<tr><td colspan="6" class="empty">暂无邮件记录。在「匹配结果」中点击「一键发送接洽内容」生成邮件。</td></tr>';return;}body.innerHTML=mailLogs.map((m,i)=>`<tr><td>${m.time}</td><td>${m.to}</td><td>${m.inv}</td><td>${m.subject}</td><td class="${m.status==="sent"?"state-sent":"state-draft"}">${m.status==="sent"?"已发送":"草稿/客户端"}</td><td><button class="tool" data-resend="${i}">重发</button></td></tr>`).join("");}
document.getElementById("mailLogBody").addEventListener("click",e=>{const btn=e.target.closest("button[data-resend]");if(!btn)return;openMailRaw(mailLogs[+btn.dataset.resend]);});
document.getElementById("platforms").innerHTML=PLATFORMS.map(p=>`<div class="pf"><a href="${p.url}" target="_blank" rel="noopener">${p.name}</a><div class="ptype">${p.type}</div><p>${p.desc}</p></div>`).join("");
